import{_ as s,c as a,d as e,o as t}from"./app-BQ7veQyr.js";const p={};function o(i,n){return t(),a("div",null,[...n[0]||(n[0]=[e(`<h1 id="gowind-shop-一个-proto-文件如何生成后端、前端、文档、校验六路代码" tabindex="-1"><a class="header-anchor" href="#gowind-shop-一个-proto-文件如何生成后端、前端、文档、校验六路代码"><span>GoWind Shop:一个 proto 文件如何生成后端、前端、文档、校验六路代码</span></a></h1><h2 id="为什么再聊-契约驱动" tabindex="-1"><a class="header-anchor" href="#为什么再聊-契约驱动"><span>为什么再聊&quot;契约驱动&quot;</span></a></h2><p>&quot;契约驱动(contract-driven)&quot;这个词被用滥了。大多数项目里它的实际含义是:后端写完接口,用 Swagger 注解生成一份文档,前端照着文档手写 fetch。文档和实现谁是事实源?没人说得清。接口改了文档没改,文档改了实现没改,前后端各自演进直到某天线上 404。</p><p>这篇文章不讲概念,讲一个<strong>可运行的工程闭环</strong>:以 <code>.proto</code> 为唯一事实源,一次 <code>buf generate</code> 同时产出六路产物——后端 gRPC 桩、后端 HTTP 桩、错误码 helper、请求校验器、PII 脱敏器、OpenAPI 文档,以及给前端的 TypeScript 客户端。文中所有配置和代码都来自一个真实仓库 go-wind-shop(GitHub: <a href="https://github.com/tx7do/go-wind-shop" target="_blank" rel="noopener noreferrer">https://github.com/tx7do/go-wind-shop</a>, Gitee: <a href="https://gitee.com/tx7do/go-wind-shop" target="_blank" rel="noopener noreferrer">https://gitee.com/tx7do/go-wind-shop</a>),你可以逐行核对。</p><p>我会先把这个闭环的每一环用真实配置讲透,再把它和主流的几种方案做横向对比,最后聊几个实际踩过的坑——包括&quot;为什么 OpenAPI 文档必须按 BFF 作用域裁剪,否则等于把核心 gRPC 全量接口暴露给公网&quot;。</p><hr><h2 id="一、闭环全景-一份-proto-六路产出" tabindex="-1"><a class="header-anchor" href="#一、闭环全景-一份-proto-六路产出"><span>一、闭环全景:一份 proto,六路产出</span></a></h2><p>先看全景。这张图里的每一个箭头,后文都会用真实配置文件落到具体行。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">                     .proto (按领域分层,唯一事实源)</span>
<span class="line">                     │  接口定义 · 数据模型 · 错误码 · 校验规则 · OpenAPI 元数据</span>
<span class="line">                     │</span>
<span class="line">                     │  buf generate  (backend/api/buf.gen.yaml)</span>
<span class="line">        ┌────────────┼─────────────────────────────────────────────────┐</span>
<span class="line">        ▼            ▼               ▼                  ▼                ▼</span>
<span class="line">   Go gRPC 桩    Go HTTP 桩     错误码 helper      请求校验/脱敏      OpenAPI v3</span>
<span class="line">   (core 用)     (BFF 用)      (protoc-gen-        (validate +         (gnostic,</span>
<span class="line">                                go-errors)          redact)            按 BFF 裁剪)</span>
<span class="line">                                                                           │</span>
<span class="line">                                                                           ▼</span>
<span class="line">                                                                    前端 TS 客户端</span>
<span class="line">                                                                   (protoc-gen-</span>
<span class="line">                                                                   typescript-http)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这套机制的核心理念是:<strong>接口、数据、错误码、校验,四者同源同生,任何一方变更都会以编译错误的形式反射到所有消费方。</strong> 没有&quot;文档忘了更新&quot;这回事——因为文档本身是产物,不是源头。</p><p>下面逐层拆。</p><hr><h2 id="二、proto-的领域分层-bff-核心-边界编码进目录" tabindex="-1"><a class="header-anchor" href="#二、proto-的领域分层-bff-核心-边界编码进目录"><span>二、proto 的领域分层:BFF/核心 边界编码进目录</span></a></h2><p>第一个要澄清的事:proto 不是按&quot;admin/app/core&quot;三个服务目录分的,而是<strong>按业务领域</strong>组织,每个领域固定带 <code>service/v1/</code> 后缀。仓库 <code>backend/api/protos/</code> 下的顶层领域有 16 个:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">backend/api/protos/</span>
<span class="line">├── admin/service/v1/        ← BFF:后台 HTTP 面 (i_*.proto,带 google.api.http 注解)</span>
<span class="line">├── app/service/v1/          ← BFF:店铺 HTTP 面 (i_*.proto,带 google.api.http 注解)</span>
<span class="line">├── catalog/service/v1/      ← 核心:gRPC(商品/品牌/类目/SKU/属性)</span>
<span class="line">├── order/service/v1/        ← 核心:gRPC(订单/订单项)</span>
<span class="line">├── payment/service/v1/      ← 核心:gRPC(支付交易/退款)</span>
<span class="line">├── identity/service/v1/     ← 核心:gRPC(用户/凭据)</span>
<span class="line">├── permission/service/v1/   ← 核心:gRPC(角色/权限/菜单/接口)</span>
<span class="line">├── authentication/...       ← 核心:gRPC(签发/校验 token)</span>
<span class="line">├── audit/...                ← 核心:gRPC(审计日志)</span>
<span class="line">├── dict/...  cart/...  shipping/...  storage/...  internal_message/...  task/...  address/...</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键的区分在 <code>google.api.http</code> 注解:<strong>只有 <code>admin</code> 和 <code>app</code> 两个 BFF 领域的 proto 带这个注解</strong>,其余 14 个核心领域的 proto 是纯 <code>rpc ... returns (...) {}</code>,没有任何 HTTP 绑定。</p><p>看一个真实的 BFF proto,<code>backend/api/protos/admin/service/v1/i_brand.proto</code>:</p><div class="language-proto line-numbers-mode" data-highlighter="prismjs" data-ext="proto"><pre><code><span class="line">rpc List (pagination.PagingRequest) returns (catalog.service.v1.ListBrandResponse) {</span>
<span class="line">  option (google.api.http) = { get: &quot;/admin/v1/mall/brands&quot; };</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意第二行:<code>returns (catalog.service.v1.ListBrandResponse)</code>——<strong>BFF proto 不重新定义数据结构,而是 import 核心领域的 DTO</strong>:</p><div class="language-proto line-numbers-mode" data-highlighter="prismjs" data-ext="proto"><pre><code><span class="line">import &quot;catalog/service/v1/brand.proto&quot;;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这是一个经过深思的设计:<strong>BFF proto 是&quot;核心 DTO 的 REST 绑定薄壳&quot;,不拥有任何数据定义。</strong> 数据模型的唯一事实源在核心领域的 proto 里,BFF 只负责把它绑到一条 HTTP 路由上。这带来一个直接的工程后果:数据模型变更只需要改一处(核心 proto),所有 BFF 的绑定自动跟随。</p><p>核心领域的 proto 长什么样?<code>backend/api/protos/catalog/service/v1/brand.proto</code> 定义了 <code>Brand</code> 消息和 <code>BrandService</code>(纯 gRPC,无 HTTP 注解):</p><div class="language-proto line-numbers-mode" data-highlighter="prismjs" data-ext="proto"><pre><code><span class="line">service BrandService {</span>
<span class="line">  rpc List (pagination.PagingRequest) returns (ListBrandResponse) {}</span>
<span class="line">  rpc Get  (GetBrandRequest) returns (Brand) {}</span>
<span class="line">  rpc Create (CreateBrandRequest) returns (Brand) {}</span>
<span class="line">  // ...</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>每个核心领域还配两个伴生文件:<code>*_error.proto</code>(kratos 错误码定义)和 <code>*_doc.proto</code>(OpenAPI 元数据注解)。错误码会在后文讲,它会被 <code>protoc-gen-go-errors</code> 编译成 Go 的类型化错误 helper。</p><p>这套分层的意义不只是整洁。它把&quot;BFF/核心&quot;的架构边界<strong>编码进了 proto 层</strong>:带 HTTP 注解的只有 admin/app,其余都是 gRPC-only。任何人扫一眼 proto 目录就知道哪些接口暴露给了公网 HTTP,哪些只在内部 gRPC 网络里流动。这是&quot;安全左移&quot;的一种形式——边界在源头就可见。</p><hr><h2 id="三、buf-配置逐行-依赖从哪来-产物往哪去" tabindex="-1"><a class="header-anchor" href="#三、buf-配置逐行-依赖从哪来-产物往哪去"><span>三、buf 配置逐行:依赖从哪来,产物往哪去</span></a></h2><h3 id="_3-1-buf-yaml-依赖清单" tabindex="-1"><a class="header-anchor" href="#_3-1-buf-yaml-依赖清单"><span>3.1 buf.yaml:依赖清单</span></a></h3><p><code>backend/api/buf.yaml</code>(v2 格式)声明了 proto 依赖的外部包:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code><span class="line"><span class="token key atrule">deps</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token string">&#39;buf.build/googleapis/googleapis&#39;</span>        <span class="token comment"># google.api.http 注解定义</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token string">&#39;buf.build/kratos/apis&#39;</span>                  <span class="token comment"># kratos 框架的 proto 扩展</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token string">&#39;buf.build/gnostic/gnostic&#39;</span>              <span class="token comment"># OpenAPI v3 注解 (gnostic)</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token string">&#39;buf.build/tx7do/pagination&#39;</span>             <span class="token comment"># 分页 proto (PagingRequest)</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token string">&#39;buf.build/go-wind/redact&#39;</span>               <span class="token comment"># PII 脱敏注解 (protoc-gen-go-redact)</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token string">&#39;buf.build/envoyproxy/protoc-gen-validate&#39;</span>  <span class="token comment"># 字段校验注解 (protoc-gen-validate)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>每一项对应一个生成器需要的能力:<code>googleapis</code> 提供 <code>google.api.http</code>(让 BFF proto 能绑 REST 路由);<code>gnostic</code> 提供 <code>gnostic.openapi.v3.property</code>(让消息字段能带 OpenAPI 元数据);<code>protoc-gen-validate</code> 提供 <code>validate</code> 字段约束(如 <code>[(validate.rules).string.min_len = 3]</code>,生成运行时校验);<code>go-wind/redact</code> 提供脱敏注解(标记哪些字段在日志/响应里要打码)。</p><p>注意这些依赖<strong>全部是 proto 定义包,不是 Go 库</strong>。buf 在构建时拉取这些 proto 定义用于编译,产物才是 Go 代码。这把&quot;接口契约&quot;和&quot;实现库&quot;彻底解耦——契约是自描述的,不依赖任何运行时反射。</p><h3 id="_3-2-buf-gen-yaml-六个本地插件" tabindex="-1"><a class="header-anchor" href="#_3-2-buf-gen-yaml-六个本地插件"><span>3.2 buf.gen.yaml:六个本地插件</span></a></h3><p>这是整个闭环的核心。<code>backend/api/buf.gen.yaml</code> 配置了六个<strong>本地 protoc 插件</strong>(不是远程 buf plugin),全部输出到 <code>gen/go</code>:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code><span class="line"><span class="token key atrule">plugins</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token key atrule">local</span><span class="token punctuation">:</span> protoc<span class="token punctuation">-</span>gen<span class="token punctuation">-</span>go              <span class="token comment"># ① Go message 代码(所有领域共享)</span></span>
<span class="line">    <span class="token key atrule">out</span><span class="token punctuation">:</span> gen/go</span>
<span class="line">  <span class="token punctuation">-</span> <span class="token key atrule">local</span><span class="token punctuation">:</span> protoc<span class="token punctuation">-</span>gen<span class="token punctuation">-</span>go<span class="token punctuation">-</span>grpc         <span class="token comment"># ② gRPC 服务桩(core 服务实现接口)</span></span>
<span class="line">    <span class="token key atrule">out</span><span class="token punctuation">:</span> gen/go</span>
<span class="line">  <span class="token punctuation">-</span> <span class="token key atrule">local</span><span class="token punctuation">:</span> protoc<span class="token punctuation">-</span>gen<span class="token punctuation">-</span>go<span class="token punctuation">-</span>http         <span class="token comment"># ③ kratos HTTP 服务桩(BFF 实现接口)</span></span>
<span class="line">    <span class="token key atrule">out</span><span class="token punctuation">:</span> gen/go</span>
<span class="line">  <span class="token punctuation">-</span> <span class="token key atrule">local</span><span class="token punctuation">:</span> protoc<span class="token punctuation">-</span>gen<span class="token punctuation">-</span>go<span class="token punctuation">-</span>errors       <span class="token comment"># ④ kratos 类型化错误码 helper</span></span>
<span class="line">    <span class="token key atrule">out</span><span class="token punctuation">:</span> gen/go</span>
<span class="line">  <span class="token punctuation">-</span> <span class="token key atrule">local</span><span class="token punctuation">:</span> protoc<span class="token punctuation">-</span>gen<span class="token punctuation">-</span>validate        <span class="token comment">#⑤ 运行时请求校验</span></span>
<span class="line">    <span class="token key atrule">out</span><span class="token punctuation">:</span> gen/gen</span>
<span class="line">  <span class="token punctuation">-</span> <span class="token key atrule">local</span><span class="token punctuation">:</span> protoc<span class="token punctuation">-</span>gen<span class="token punctuation">-</span>go<span class="token punctuation">-</span>redact       <span class="token comment"># ⑥ PII 脱敏(日志/响应打码)</span></span>
<span class="line">    <span class="token key atrule">out</span><span class="token punctuation">:</span> gen/go</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>逐个说清楚每个插件干什么:</p><p><strong>① protoc-gen-go</strong>:把每个 <code>message</code> 编译成 Go struct。这是 protobuf 的基础能力,不赘述。</p><p><strong>② protoc-gen-go-grpc</strong>:为每个 <code>service</code> 生成 gRPC server interface 和 client stub。core 服务实现 <code>catalogV1.BrandServiceServer</code> 接口;BFF 服务通过 <code>catalogV1.BrandServiceClient</code> 调用 core。这就是上一节&quot;BFF 转发 gRPC 到 core&quot;的代码基础——client 桩是生成的,不是手写的。</p><p><strong>③ protoc-gen-go-http</strong>:kratos 特有的插件。它读 <code>google.api.http</code> 注解,<strong>为每个带注解的 RPC 生成一个 HTTP handler 桩和 server interface</strong>。这是&quot;BFF proto 绑 REST 路由&quot;的实现机制——BFF service 实现的是 <code>adminV1.BrandServiceHTTPServer</code> 接口(注意是 HTTPServer,不是 gRPC server),kratos 的 HTTP transport 根据注解把 <code>/admin/v1/mall/brands</code> 这条路由分派到这个接口的实现。同一个业务接口,在 BFF 侧是 HTTP,在 core 侧是 gRPC,两者由同一份 proto 的不同注解决定。</p><p><strong>④ protoc-gen-go-errors</strong>:读 <code>*_error.proto</code> 里定义的错误码,生成 Go 的类型化错误 helper。例如 <code>catalog_error.proto</code> 定义了 <code>NotFound</code> 错误码,生成的代码长这样:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// 生成产物</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">ErrorNotFound</span><span class="token punctuation">(</span>format <span class="token builtin">string</span><span class="token punctuation">,</span> a <span class="token operator">...</span>any<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token operator">&amp;</span>catalogV1<span class="token punctuation">.</span>ErrorNotFound<span class="token punctuation">{</span> <span class="token comment">/* kratos error with code */</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>业务代码里 <code>return nil, catalogV1.ErrorNotFound(&quot;brand %d&quot;, id)</code> 返回的是<strong>类型化、带 HTTP 状态码映射</strong>的错误。kratos 框架会把这个错误转成对应 HTTP 状态码(404)和结构化 JSON 响应。这比 <code>errors.New(&quot;not found&quot;)</code> + 手写 <code>http.Error</code> 工程化得多——错误码、消息、状态码三者绑定,且与 proto 同源。</p><p><strong>⑤ protoc-gen-validate</strong>:读 <code>[(validate.rules)...]</code> 注解,生成运行时校验代码。例如 proto 里写 <code>string name = 1 [(validate.rules).string.min_len = 1, (validate.rules).string.max_len = 100];</code>,生成的代码会在请求进入 handler 前校验长度,不通过直接返回 400。这把&quot;参数校验&quot;从业务代码里抽出来,变成声明式。</p><p><strong>⑥ protoc-gen-go-redact</strong>:读 redact 注解,生成字段脱敏逻辑。标记为敏感的字段(如手机号、邮箱),在日志输出或响应序列化时自动打码。这是 PII 合规的基础设施。</p><h3 id="_3-3-managed-块-go-package-的集中管理" tabindex="-1"><a class="header-anchor" href="#_3-3-managed-块-go-package-的集中管理"><span>3.3 managed 块:go_package 的集中管理</span></a></h3><p><code>buf.gen.yaml</code> 还有一个 <code>managed</code> 段,为每个 proto 目录集中设置 <code>go_package</code>:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code><span class="line"><span class="token key atrule">managed</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">enabled</span><span class="token punctuation">:</span> <span class="token boolean important">true</span></span>
<span class="line">  <span class="token key atrule">override</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token punctuation">-</span> <span class="token key atrule">file_option</span><span class="token punctuation">:</span> go_package</span>
<span class="line">      <span class="token key atrule">path</span><span class="token punctuation">:</span> catalog/service/v1</span>
<span class="line">      <span class="token key atrule">value</span><span class="token punctuation">:</span> go<span class="token punctuation">-</span>wind<span class="token punctuation">-</span>shop/api/gen/go/catalog/service/v1;catalogpb</span>
<span class="line">    <span class="token punctuation">-</span> <span class="token key atrule">file_option</span><span class="token punctuation">:</span> go_package</span>
<span class="line">      <span class="token key atrule">path</span><span class="token punctuation">:</span> admin/service/v1</span>
<span class="line">      <span class="token key atrule">value</span><span class="token punctuation">:</span> go<span class="token punctuation">-</span>wind<span class="token punctuation">-</span>shop/api/gen/go/admin/service/v1;adminpb</span>
<span class="line">    <span class="token comment"># ... 每个领域一条</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这解决了&quot;proto 该 import 什么路径、生成代码该放哪个包&quot;的治理问题。没有这个,每个 <code>.proto</code> 都得手写 <code>option go_package = &quot;...&quot;</code>,改包名要改几十个文件。集中管理后,包结构是配置驱动的,一次修改全局生效。</p><p>最终产物落在 <code>backend/api/gen/go/&lt;领域&gt;/service/v1/*.pb.go</code>,覆盖全部 16 个领域。这些产物是 commit 进仓库的(不是运行时生成),便于 review 和 IDE 索引。</p><hr><h2 id="四、openapi-文档的按作用域裁剪-一个容易被忽略的安全细节" tabindex="-1"><a class="header-anchor" href="#四、openapi-文档的按作用域裁剪-一个容易被忽略的安全细节"><span>四、OpenAPI 文档的按作用域裁剪:一个容易被忽略的安全细节</span></a></h2><p>这一节讲一个踩坑点,它直接关乎接口安全。</p><h3 id="_4-1-问题-全局-openapi-会泄漏核心接口" tabindex="-1"><a class="header-anchor" href="#_4-1-问题-全局-openapi-会泄漏核心接口"><span>4.1 问题:全局 OpenAPI 会泄漏核心接口</span></a></h3><p>OpenAPI 文档默认是全局生成的——把所有 proto 的 HTTP 注解都扫进一份 <code>openapi.yaml</code>。如果直接这么做,会遇到一个麻烦:核心领域的 proto 没有 HTTP 注解,所以不会进文档,看起来没问题。</p><p>但真正的坑在 BFF 侧。admin BFF 和 app BFF 都各自暴露了一组 HTTP 路由(分别绑 <code>/admin/v1/...</code> 和 <code>/app/v1/...</code>)。如果把两个 BFF 的路由都扫进<strong>同一份</strong> OpenAPI 文档,会发生什么?</p><ul><li>文档里同时出现后台管理接口和买家侧接口。</li><li>这份文档挂载在 Swagger UI 上(<code>/swagger-ui</code>)。如果挂载在 admin BFF 上,但文档里含 app BFF 的路由,等于在 admin 的 Swagger 里暴露了买家的接口面;反之亦然。</li><li>更糟的是,如果将来某个核心领域被人加了 HTTP 注解(哪怕是误加),它会悄无声息地出现在 Swagger 里——而那个接口本该只在内部 gRPC 网络可见。</li></ul><h3 id="_4-2-解法-按-bff-作用域单独生成" tabindex="-1"><a class="header-anchor" href="#_4-2-解法-按-bff-作用域单独生成"><span>4.2 解法:按 BFF 作用域单独生成</span></a></h3><p>仓库的解法是<strong>为每个 BFF 单独配一个 OpenAPI 生成配置</strong>,只扫该 BFF 的 proto 目录。<code>backend/api/buf.admin.openapi.gen.yaml</code>:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code><span class="line"><span class="token key atrule">inputs</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token key atrule">directory</span><span class="token punctuation">:</span> protos</span>
<span class="line">    <span class="token key atrule">paths</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> protos/admin/service/v1      <span class="token comment"># 只扫 admin BFF 的 proto</span></span>
<span class="line"><span class="token key atrule">plugins</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token key atrule">local</span><span class="token punctuation">:</span> protoc<span class="token punctuation">-</span>gen<span class="token punctuation">-</span>openapi         <span class="token comment"># gnostic 提供的 OpenAPI 生成器</span></span>
<span class="line">    <span class="token key atrule">out</span><span class="token punctuation">:</span> ../app/admin/service/cmd/server/assets</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键在 <code>paths: - protos/admin/service/v1</code>——<strong>显式限定输入只含 admin BFF 的 proto</strong>。产出的 <code>openapi.yaml</code> 因此只包含 <code>/admin/v1/...</code> 路由,不会有任何 app BFF 或 core 的接口。</p><p>app BFF 有对称的 <code>buf.app.openapi.gen.yaml</code>,只扫 <code>protos/app/service/v1</code>,输出到 <code>app/app/service/cmd/server/assets/</code>。</p><h3 id="_4-3-文档嵌入二进制-运行时挂载" tabindex="-1"><a class="header-anchor" href="#_4-3-文档嵌入二进制-运行时挂载"><span>4.3 文档嵌入二进制 + 运行时挂载</span></a></h3><p>生成的 <code>openapi.yaml</code> 不是放静态文件目录,而是用 <code>//go:embed</code> 嵌进 BFF 二进制。<code>app/admin/service/cmd/server/assets/assets.go</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">//go:embed openapi.yaml</span></span>
<span class="line"><span class="token keyword">var</span> openapiYaml <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">byte</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>运行时,<code>server.yaml</code> 里 <code>enable_swagger: true</code> 时,kratos 的 swagger-ui 中间件用这份内存数据挂载 <code>/swagger-ui</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">if</span> cfg<span class="token punctuation">.</span><span class="token function">GetServer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">GetRest</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">GetEnableSwagger</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    swaggerUI<span class="token punctuation">.</span><span class="token function">RegisterSwaggerUIServerWithOption</span><span class="token punctuation">(</span>srv<span class="token punctuation">,</span></span>
<span class="line">        swaggerUI<span class="token punctuation">.</span><span class="token function">WithMemoryData</span><span class="token punctuation">(</span>assets<span class="token punctuation">.</span>OpenApiData<span class="token punctuation">,</span> <span class="token string">&quot;yaml&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样有几个好处:文档与二进制同版本,不会出现&quot;线上跑的是旧文档&quot;;部署不需要额外拷静态文件;生产环境关掉 <code>enable_swagger</code> 就彻底下线文档。</p><p><strong>但有个前提条件必须满足</strong>:作用域裁剪配置(4.2)必须先做对。否则嵌入的就是全量文档,Swagger 一开就把不该暴露的接口全抖出来。这个踩坑点的教训是:<strong>OpenAPI 文档的可见范围要作为一个显式的安全边界来管理,不能默认全量。</strong></p><h3 id="_4-4-前端-typescript-客户端-同源产物" tabindex="-1"><a class="header-anchor" href="#_4-4-前端-typescript-客户端-同源产物"><span>4.4 前端 TypeScript 客户端:同源产物</span></a></h3><p>还有一组配置 <code>buf.admin.typescript.gen.yaml</code> 和 <code>buf.vue.app.typescript.gen.yaml</code>,分别给后台 Vue 和店铺 Nuxt 生成 TypeScript HTTP 客户端。前端的 API 调用因此与后端路由同源——proto 改了字段,前端编译期就报错。这不是&quot;文档说有这个字段&quot;,而是&quot;类型定义里确实有这个字段&quot;,二者由同一份 proto 保证一致。</p><hr><h2 id="五、错误码-从字符串到类型化的工程化" tabindex="-1"><a class="header-anchor" href="#五、错误码-从字符串到类型化的工程化"><span>五、错误码:从字符串到类型化的工程化</span></a></h2><p>前面提了 <code>protoc-gen-go-errors</code>,这里展开讲,因为它体现了契约驱动的一个深层价值:<strong>把&quot;错误&quot;从运行时的字符串,提升为编译期的类型。</strong></p><h3 id="_5-1-错误码定义在-proto-里" tabindex="-1"><a class="header-anchor" href="#_5-1-错误码定义在-proto-里"><span>5.1 错误码定义在 proto 里</span></a></h3><p>每个领域有 <code>*_error.proto</code>,用 kratos 的扩展语法定义错误码。例如 <code>catalog_error.proto</code> 定义了 <code>NotFound</code>、<code>BadRequest</code>、<code>InternalServerError</code> 等,每个绑定一个 HTTP 状态码和 gRPC 状态码。这些定义是 proto 的一部分,和消息定义同源。</p><h3 id="_5-2-生成产物-类型化-helper" tabindex="-1"><a class="header-anchor" href="#_5-2-生成产物-类型化-helper"><span>5.2 生成产物:类型化 helper</span></a></h3><p><code>protoc-gen-go-errors</code> 把每个错误码生成一个 Go 类型和一个 helper 函数:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// 生成产物,不要手改</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">ErrorNotFound</span><span class="token punctuation">(</span>format <span class="token builtin">string</span><span class="token punctuation">,</span> a <span class="token operator">...</span>any<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span> <span class="token operator">...</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">IsNotFound</span><span class="token punctuation">(</span>err <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token builtin">bool</span> <span class="token punctuation">{</span> <span class="token operator">...</span> <span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>业务代码这样用:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">brand<span class="token punctuation">,</span> err <span class="token operator">:=</span> r<span class="token punctuation">.</span>repo<span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> id<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> catalogV1<span class="token punctuation">.</span><span class="token function">ErrorNotFound</span><span class="token punctuation">(</span><span class="token string">&quot;brand %d&quot;</span><span class="token punctuation">,</span> id<span class="token punctuation">)</span>  <span class="token comment">// 类型化错误</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>kratos 框架拦截这个返回值,根据错误码映射查表把它转成 HTTP 404 + 结构化 JSON 响应:</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code><span class="line"><span class="token punctuation">{</span><span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">404</span><span class="token punctuation">,</span> <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;brand 123 not found&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;reason&quot;</span><span class="token operator">:</span> <span class="token string">&quot;NOT_FOUND&quot;</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_5-3-对比-这解决了什么" tabindex="-1"><a class="header-anchor" href="#_5-3-对比-这解决了什么"><span>5.3 对比:这解决了什么</span></a></h3><p>对比手写接口的常见做法:<code>errors.New(&quot;not found&quot;)</code> + handler 里 <code>if err != nil { w.WriteHeader(404); w.Write(...) }</code>。问题在于:</p><ul><li>错误码、HTTP 状态码、响应格式三者各自手写,容易不一致(比如错误码 404 配了 200 状态码)。</li><li>前端没法类型化地判断错误种类,只能字符串匹配。</li><li>错误信息可能直接泄漏内部细节(stack trace、SQL 错误),没有统一的脱敏层。</li></ul><p>类型化错误让这三者绑定到 proto 定义里,改错误码要改 proto,所有消费方自动跟随。前端的 TS 客户端也能生成对应的错误类型,做到 <code>catch (e) { if (e instanceof NotFoundError) ... }</code>。</p><hr><h2 id="六、ent-schema-即代码-以及四个-feature-flag-的取舍" tabindex="-1"><a class="header-anchor" href="#六、ent-schema-即代码-以及四个-feature-flag-的取舍"><span>六、Ent:Schema 即代码,以及四个 feature flag 的取舍</span></a></h2><p>proto 解决了&quot;接口契约&quot;,数据层的契约由 Ent 解决。Ent 是 entgo.io 的 ORM,核心思想是 <strong>Schema 即代码</strong>——实体、字段、索引、外键、表名都用 Go 代码定义,通过代码生成产出类型安全的查询 API。</p><h3 id="_6-1-ent-生成命令逐行" tabindex="-1"><a class="header-anchor" href="#_6-1-ent-生成命令逐行"><span>6.1 Ent 生成命令逐行</span></a></h3><p><code>backend/app.mk</code> 里每个 core 服务执行的 <code>ent</code> 目标:</p><div class="language-make line-numbers-mode" data-highlighter="prismjs" data-ext="make"><pre><code><span class="line">ent:</span>
<span class="line">    @ent generate --feature privacy --feature entql \\</span>
<span class="line">        --feature sql/modifier --feature sql/upsert --feature sql/lock \\</span>
<span class="line">        ./internal/data/ent/schema</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>四个 feature flag,每个都有具体的工程目的:</p><p><strong><code>--feature privacy</code></strong>:启用 Ent 的 <a href="https://entgo.io/docs/privacy/" target="_blank" rel="noopener noreferrer">privacy 策略</a>。这是行级安全的基础——允许在 Schema 上挂 <code>Policy</code>,Ent 会在每次查询/变更时自动注入过滤条件。具体怎么用、怎么实现行级隔离,涉及鉴权链,这里先记住它是&quot;框架级强制 WHERE 注入&quot;的开关。</p><p><strong><code>--feature entql</code></strong>:允许在查询里注入原生 SQL 谓词。privacy 策略注入的 <code>WHERE</code> 条件就是通过 entql 的 <code>func(s *sql.Selector)</code> 钩子实现的——没有这个 flag,privacy 策略没法改写查询。</p><p><strong><code>--feature sql/modifier</code></strong>:支持查询修饰器,用于 <code>builder.Modify(whereCond...)</code> 这种动态拼装。分页+多条件筛选的列表查询靠它。</p><p><strong><code>--feature sql/upsert</code> 和 <code>--feature sql/lock</code></strong>:upsert 支持高并发下的&quot;存在则更新,不存在则插入&quot;(库存扣减、计数器);<code>sql/lock</code> 支持显式行锁(<code>SELECT ... FOR UPDATE</code>),订单状态机变更时需要它防止并发改状态。</p><p>这五个 flag 不是随便开的,每一个都对应一个真实的业务场景需要。</p><h3 id="_6-2-schema-即代码-mixin-统一审计列" tabindex="-1"><a class="header-anchor" href="#_6-2-schema-即代码-mixin-统一审计列"><span>6.2 Schema 即代码:Mixin 统一审计列</span></a></h3><p>看一个真实的 Schema,<code>backend/app/core/service/internal/data/ent/schema/brand.go</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>Brand<span class="token punctuation">)</span> <span class="token function">Annotations</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>schema<span class="token punctuation">.</span>Annotation <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>schema<span class="token punctuation">.</span>Annotation<span class="token punctuation">{</span></span>
<span class="line">        entsql<span class="token punctuation">.</span>Annotation<span class="token punctuation">{</span></span>
<span class="line">            Table<span class="token punctuation">:</span> <span class="token string">&quot;mall_brands&quot;</span><span class="token punctuation">,</span> Charset<span class="token punctuation">:</span> <span class="token string">&quot;utf8mb4&quot;</span><span class="token punctuation">,</span> Collation<span class="token punctuation">:</span> <span class="token string">&quot;utf8mb4_bin&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">        schema<span class="token punctuation">.</span><span class="token function">Comment</span><span class="token punctuation">(</span><span class="token string">&quot;品牌表&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>Brand<span class="token punctuation">)</span> <span class="token function">Fields</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>ent<span class="token punctuation">.</span>Field <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>ent<span class="token punctuation">.</span>Field<span class="token punctuation">{</span></span>
<span class="line">        field<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">&quot;logo_url&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Optional</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Nillable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>Brand<span class="token punctuation">)</span> <span class="token function">Mixin</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>ent<span class="token punctuation">.</span>Mixin <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>ent<span class="token punctuation">.</span>Mixin<span class="token punctuation">{</span></span>
<span class="line">        mixin<span class="token punctuation">.</span>AutoIncrementId<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span>    <span class="token comment">// 自增主键 id</span></span>
<span class="line">        mixin<span class="token punctuation">.</span>TimeAt<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span>             <span class="token comment">// created_at / updated_at / deleted_at</span></span>
<span class="line">        mixin<span class="token punctuation">.</span>OperatorID<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span>         <span class="token comment">// created_by / updated_by / deleted_by</span></span>
<span class="line">        mixin<span class="token punctuation">.</span>SortOrder<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span>          <span class="token comment">// sort_order</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里要讲的是 <code>Mixin</code>。<code>Mixin</code> 是 Ent 的&quot;Schema 片段复用&quot;机制——把一组字段和索引打包,多个 Schema 共享。这个仓库用的 Mixin 来自 <code>github.com/tx7do/go-crud/entgo/mixin</code>,四个 Mixin 注入了所有业务表共有的&quot;审计列&quot;:</p><ul><li><code>AutoIncrementId</code>:自增 <code>id</code> 主键。</li><li><code>TimeAt</code>:<code>created_at</code>、<code>updated_at</code>、<code>deleted_at</code> 三列,自动维护(创建时填 created_at,更新时刷 updated_at,删除时置 deleted_at 实现软删)。</li><li><code>OperatorID</code>:<code>created_by</code>、<code>updated_by</code>、<code>deleted_by</code>,记录每行的操作者 id。</li><li><code>SortOrder</code>:<code>sort_order</code>,前端列表排序用。</li></ul><p>为什么用 Mixin 而不是每张表手写这些列?这是个值得讲的取舍。</p><p><strong>踩坑叙事</strong>:如果每张表手写这四列,几十张表就是几百行重复代码,而且容易漏写——某张表忘了加 <code>deleted_at</code>,软删就失效;某张表忘了加 <code>created_by</code>,审计就断链。Mixin 把这些&quot;必须存在但容易漏&quot;的列收敛成一行 <code>mixin.TimeAt{}</code>,漏写的成本从&quot;运行时出 bug&quot;降到了&quot;编译期缺一行&quot;。这和契约驱动的理念一致:<strong>把容易出错的人工操作,变成框架强制。</strong></p><p>注意 <code>created_by</code> 这列和前面 BFF service 里的这行对应:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">req<span class="token punctuation">.</span>Data<span class="token punctuation">.</span>CreatedBy <span class="token operator">=</span> trans<span class="token punctuation">.</span><span class="token function">Ptr</span><span class="token punctuation">(</span>operator<span class="token punctuation">.</span>UserId<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>BFF 从鉴权上下文取操作者 id,塞进请求的 <code>CreatedBy</code> 字段,这个字段映射到 Ent 的 <code>created_by</code> 列(由 OperatorID mixin 创建)。整条链路:JWT → 鉴权中间件解析出 operator → BFF 注入请求 → Ent mixin 落库。操作者溯源是端到端、框架强制的,不靠业务代码自觉。</p><h3 id="_6-3-ent-vs-gorm-vs-sqlc-三种数据层方案对比" tabindex="-1"><a class="header-anchor" href="#_6-3-ent-vs-gorm-vs-sqlc-三种数据层方案对比"><span>6.3 Ent vs GORM vs sqlc:三种数据层方案对比</span></a></h3><p>这是项目选型时绕不开的对比。我把三者的取舍讲清楚。</p><table><thead><tr><th>维度</th><th>Ent</th><th>GORM</th><th>sqlc</th></tr></thead><tbody><tr><td>Schema 定义</td><td>Go 代码(Schema 即代码)</td><td>struct tag</td><td>手写 SQL + 生成 Go</td></tr><tr><td>类型安全</td><td>编译期(生成代码强类型)</td><td>运行时(interface{})</td><td>编译期(生成代码强类型)</td></tr><tr><td>行级安全(privacy)</td><td>原生支持,框架强制</td><td>无,靠业务自觉</td><td>无,靠业务自觉</td></tr><tr><td>索引/外键/表名</td><td>Schema 里声明</td><td>struct tag 声明</td><td>SQL 里声明</td></tr><tr><td>迁移</td><td><code>client.Schema.Create()</code> 自动 DDL</td><td>AutoMigrate</td><td>手写迁移</td></tr><tr><td>学习曲线</td><td>中(需学 Schema/生成流程)</td><td>低(最普及)</td><td>中(需写 SQL)</td></tr></tbody></table><p>对这个项目而言,<strong>Ent 的 <code>privacy</code> 是决定性因素</strong>。GORM 和 sqlc 都没有&quot;框架级强制 WHERE 注入&quot;的能力——多租户、多用户的行级隔离如果用 GORM,只能靠每个查询手写 <code>WHERE tenant_id = ? AND user_id = ?</code>,漏写一处就是越权漏洞。Ent privacy 把这个变成 Schema 上的一次声明:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>Order<span class="token punctuation">)</span> <span class="token function">Policy</span><span class="token punctuation">(</span><span class="token punctuation">)</span> ent<span class="token punctuation">.</span>Policy <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> appPrivacy<span class="token punctuation">.</span>UserPrivacy<span class="token punctuation">{</span><span class="token punctuation">}</span>   <span class="token comment">// 框架自动注入 WHERE user_id = current_user</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>之后所有对 <code>Order</code> 表的查询,Ent 都会自动追加 <code>WHERE user_id = &lt;viewer.uid&gt;</code>,业务代码完全无感。这个能力 GORM 给不了,这是项目选 Ent 的核心理由。</p><p>代价是 Ent 的学习曲线和生成产物的体积。Ent 生成的代码(<code>ent/</code> 目录)体积很大,git diff 噪音多,需要团队约定 review 边界。但相比&quot;漏写一处 WHERE 导致越权&quot;的风险,这个代价值得。</p><hr><h2 id="七、wire-编译期依赖注入的取舍" tabindex="-1"><a class="header-anchor" href="#七、wire-编译期依赖注入的取舍"><span>七、Wire:编译期依赖注入的取舍</span></a></h2><p>最后一个代码生成的环节是依赖注入。三个服务都用 <a href="https://github.com/google/wire" target="_blank" rel="noopener noreferrer">Google Wire</a> 做编译期 DI。</p><h3 id="_7-1-injector-桩与-providerset" tabindex="-1"><a class="header-anchor" href="#_7-1-injector-桩与-providerset"><span>7.1 injector 桩与 ProviderSet</span></a></h3><p>每个服务的 <code>cmd/server/wire.go</code> 是 injector 桩,带 <code>//go:build wireinject</code> 构建标签:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">//go:build wireinject</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">initApp</span><span class="token punctuation">(</span><span class="token operator">*</span>bootstrap<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>kratos<span class="token punctuation">.</span>App<span class="token punctuation">,</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">panic</span><span class="token punctuation">(</span>wire<span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span></span>
<span class="line">        serverProviders<span class="token punctuation">.</span>ProviderSet<span class="token punctuation">,</span></span>
<span class="line">        serviceProviders<span class="token punctuation">.</span>ProviderSet<span class="token punctuation">,</span></span>
<span class="line">        dataProviders<span class="token punctuation">.</span>ProviderSet<span class="token punctuation">,</span></span>
<span class="line">        newApp<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>make wire</code> 跑 <code>wire ./cmd/server</code>,Wire 读三个 <code>ProviderSet</code>(分别在 <code>internal/{data,server,service}/providers/wire_set.go</code>),生成 <code>wire_gen.go</code>(<code>//go:build !wireinject</code>),把整张依赖图具象化。</p><p>一个 <code>ProviderSet</code> 长这样(admin BFF 的 data 层):</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">var</span> ProviderSet <span class="token operator">=</span> wire<span class="token punctuation">.</span><span class="token function">NewSet</span><span class="token punctuation">(</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewRedisClient<span class="token punctuation">,</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewMinIoClient<span class="token punctuation">,</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewDiscovery<span class="token punctuation">,</span>            <span class="token comment">// etcd 服务发现</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewAuthorizer<span class="token punctuation">,</span>           <span class="token comment">// Casbin/OPA 引擎</span></span>
<span class="line">    auth<span class="token punctuation">.</span>NewTokenChecker<span class="token punctuation">,</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewBrandServiceClient<span class="token punctuation">,</span>   <span class="token comment">// core gRPC client 桩(生成代码)</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewProductServiceClient<span class="token punctuation">,</span></span>
<span class="line">    data<span class="token punctuation">.</span>NewOrderServiceClient<span class="token punctuation">,</span></span>
<span class="line">    <span class="token comment">// ... 约 40 个 core gRPC client 工厂</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>core 服务的 <code>ProviderSet</code> 则装配 <code>NewEntClient</code> → 每个 <code>NewXxxRepo</code> → 每个 <code>NewXxxService</code> → <code>NewGrpcServer</code>。</p><h3 id="_7-2-wire-vs-运行时-di-的对比" tabindex="-1"><a class="header-anchor" href="#_7-2-wire-vs-运行时-di-的对比"><span>7.2 Wire vs 运行时 DI 的对比</span></a></h3><table><thead><tr><th>维度</th><th>Wire(编译期)</th><th>dig/fx(运行时)</th><th>手写 main</th></tr></thead><tbody><tr><td>注入时机</td><td>编译期代码生成</td><td>运行时反射</td><td>手写</td></tr><tr><td>启动开销</td><td>零</td><td>反射+图构建</td><td>零</td></tr><tr><td>依赖错误暴露</td><td>编译期</td><td>运行时(启动时 panic)</td><td>运行时</td></tr><tr><td>可读性</td><td>wire_gen.go 可 diff</td><td>隐式,难追踪</td><td>显式但冗长</td></tr><tr><td>产物体积</td><td>wire_gen.go 很大</td><td>无额外产物</td><td>无</td></tr></tbody></table><p>Wire 的核心优势是<strong>依赖错误在编译期暴露</strong>。如果某个 service 缺少依赖,<code>wire</code> 命令直接报错,二进制根本编不出来。dig/fx 要等到启动时才发现。对一个有几百个 provider 的微服务,编译期暴露的价值很大。</p><p>代价是 <code>wire_gen.go</code> 体积大、可读性差。但它本质是&quot;依赖关系的可 diff 快照&quot;——review 它能快速看出谁依赖谁,反而比运行时 DI 的隐式图更透明。这个项目选 Wire 的理由和选 Ent 类似:<strong>用编译期保证换取运行时安全。</strong></p><hr><h2 id="八、fieldmask-proto-怎么驱动部分更新" tabindex="-1"><a class="header-anchor" href="#八、fieldmask-proto-怎么驱动部分更新"><span>八、FieldMask:proto 怎么驱动部分更新</span></a></h2><p>讲一个容易被忽略但很实际的契约驱动细节:部分更新(Partial Update)。</p><h3 id="_8-1-问题-全量更新会覆盖" tabindex="-1"><a class="header-anchor" href="#_8-1-问题-全量更新会覆盖"><span>8.1 问题:全量更新会覆盖</span></a></h3><p>UPDATE 操作如果做全量更新,会有个经典坑:前端只改了 <code>name</code>,但请求体里没传 <code>logo_url</code>(因为前端表单没这个字段),后端如果用请求体直接覆盖整行,<code>logo_url</code> 就被置空了。</p><h3 id="_8-2-proto-的-fieldmask" tabindex="-1"><a class="header-anchor" href="#_8-2-proto-的-fieldmask"><span>8.2 proto 的 FieldMask</span></a></h3><p>proto 的解法是 <code>google.protobuf.FieldMask</code>。每个 Update 请求带一个 <code>update_mask</code> 字段,列出本次要更新的字段路径:</p><div class="language-proto line-numbers-mode" data-highlighter="prismjs" data-ext="proto"><pre><code><span class="line">message UpdateBrandRequest {</span>
<span class="line">  optional Brand data = 1;</span>
<span class="line">  optional google.protobuf.FieldMask update_mask = 2;</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>前端只发变更字段,并在 <code>update_mask</code> 里声明哪些字段变了。后端的 repo 根据这个 mask 只更新对应列,其余列不动。</p><h3 id="_8-3-ent-侧的落地" tabindex="-1"><a class="header-anchor" href="#_8-3-ent-侧的落地"><span>8.3 Ent 侧的落地</span></a></h3><p><code>core/.../data/brand_repo.go</code> 的 <code>Update</code> 用了 <code>--feature sql/modifier</code> 提供的能力,根据 <code>update_mask</code> 动态拼装 UPDATE 语句的 SET 子句:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>r <span class="token operator">*</span>BrandRepo<span class="token punctuation">)</span> <span class="token function">Update</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> req <span class="token operator">*</span>catalogV1<span class="token punctuation">.</span>UpdateBrandRequest<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token operator">*</span>catalogV1<span class="token punctuation">.</span>Brand<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// update_mask 决定哪些字段进 SET 子句</span></span>
<span class="line">    <span class="token comment">// 没在 mask 里的字段不会被覆盖</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这套机制是端到端的:proto 定义 mask → 生成 Go 类型 → 前端 TS 客户端生成对应的 mask API → 后端 Ent 根据_mask 拼装 SQL。没有一个环节需要手写&quot;哪些字段能更新&quot;的逻辑——它由 proto 声明,生成代码落地。</p><p>对比手写接口的常见做法:后端手写 <code>if req.Name != nil { update.SetName(*req.Name) }</code> 逐字段判断,漏一个就是 bug,多一个就是越权更新。FieldMask 把这个变成声明式,且由 proto 强制两端一致。</p><hr><h2 id="九、横向对比-这套方案-vs-另三种主流路径" tabindex="-1"><a class="header-anchor" href="#九、横向对比-这套方案-vs-另三种主流路径"><span>九、横向对比:这套方案 vs 另三种主流路径</span></a></h2><p>把这套&quot;proto-first + Ent + Wire&quot;的方案,和另外三种常见路径做横向对比,讲清楚各自适合什么。</p><h3 id="路径-a-openapi-first-swagger-注解驱动" tabindex="-1"><a class="header-anchor" href="#路径-a-openapi-first-swagger-注解驱动"><span>路径 A:OpenAPI-first(Swagger 注解驱动)</span></a></h3><p>这是很多 Java/Node 项目的做法:后端用 Swagger 注解标注接口,生成 OpenAPI 文档,前端照文档手写 client。</p><ul><li><strong>优点</strong>:OpenAPI 是开放标准,工具链丰富。</li><li><strong>缺点</strong>:文档是&quot;从实现反推&quot;的,注解和实现可能不一致;没有 gRPC 的能力(OpenAPI 只描述 HTTP);前端 client 仍需手写或用通用生成器,类型安全不如 proto。</li><li><strong>适合</strong>:纯 HTTP 项目,团队对 proto 有抵触。</li></ul><p>这个项目没有选它,核心原因是它<strong>不能同时生成 gRPC 和 HTTP</strong>。三服务 BFF 架构里,BFF 暴露 HTTP、core 暴露 gRPC,两者要共享同一套 DTO——只有 proto 能做到&quot;一份定义,两种传输&quot;。OpenAPI-first 只能描述 HTTP,无法覆盖 core 的 gRPC 面。</p><h3 id="路径-b-手写接口-手写文档" tabindex="-1"><a class="header-anchor" href="#路径-b-手写接口-手写文档"><span>路径 B:手写接口 + 手写文档</span></a></h3><p>最常见的路径。后端用 gin/echo 手写 handler,Swagger 文档手写或用 swag 注解。</p><ul><li><strong>优点</strong>:上手快,无学习曲线。</li><li><strong>缺点</strong>:文档和实现漂移是常态;前端没有类型化 client;错误码、校验、脱敏全靠手写,漏一处就是 bug 或漏洞;多传输(gRPC+HTTP)要写两套。</li><li><strong>适合</strong>:原型期、小项目、技术债可接受的项目。</li></ul><p>这个项目面向&quot;企业级出海电商脚手架&quot;,要支撑几十个领域、上百个接口、多传输、行级隔离、审计——手写接口的维护成本在这个规模下会失控。</p><h3 id="路径-c-graphql-orm" tabindex="-1"><a class="header-anchor" href="#路径-c-graphql-orm"><span>路径 C:GraphQL + ORM</span></a></h3><p>前端驱动查询,后端用 GraphQL schema + ORM。</p><ul><li><strong>优点</strong>:前端灵活,按需取字段;schema 即契约。</li><li><strong>缺点</strong>:GraphQL 的 N+1 问题、鉴权粒度(每个 resolver 都要鉴权)、缓存复杂度都比 REST 高;ORM 仍需选型,行级隔离仍要自己实现;服务端渲染 SSR 对 GraphQL 不友好。</li><li><strong>适合</strong>:前端需求多变、BFF 聚合多后端的场景。</li></ul><p>这个项目没选它,主要原因是电商场景的查询模式相对固定(商品列表、详情、订单流程),GraphQL 的灵活性收益不大,但它的鉴权复杂度和 N+1 风险在这个场景下是净负担。而且 SEO 对电商前台是刚需,REST + URL locale 比 GraphQL 更利于爬虫索引。</p><h3 id="路径-d-本方案-proto-first-ent-wire" tabindex="-1"><a class="header-anchor" href="#路径-d-本方案-proto-first-ent-wire"><span>路径 D(本方案):proto-first + Ent + Wire</span></a></h3><ul><li><strong>优点</strong>:接口/数据/错误码/校验同源;多传输同源;行级隔离框架强制;依赖错误编译期暴露;前端类型化 client 自动生成。</li><li><strong>缺点</strong>:学习曲线陡(kratos+Ent+Wire+buf);生成产物体积大,diff 噪音多;proto 的表达力有边界(复杂业务逻辑仍要写在 service 里);生态比 Java/Node 小。</li><li><strong>适合</strong>:愿意投资工程基建、需要多传输、需要强隔离的团队;不适合快速原型或小团队。</li></ul><p>没有银弹。这套方案的代价是显式的:学习曲线和生成产物。它的收益也是显式的:契约不漂移、行级隔离框架级强制、多传输同源。对这个项目的目标场景(企业级、多语言、多租户、审计合规),收益大于代价。</p><hr><h2 id="十、三个实战踩坑点" tabindex="-1"><a class="header-anchor" href="#十、三个实战踩坑点"><span>十、三个实战踩坑点</span></a></h2><p>最后讲三个真实的踩坑点,都是这套机制在实际演进中暴露的。</p><h3 id="_10-1-openapi-作用域裁剪-不做等于裸奔" tabindex="-1"><a class="header-anchor" href="#_10-1-openapi-作用域裁剪-不做等于裸奔"><span>10.1 OpenAPI 作用域裁剪:不做等于裸奔</span></a></h3><p>前面 4.2 讲过这个。补充一个实际后果:如果 admin BFF 的 Swagger 里混进了 app BFF 的买家侧接口,运营在后台 Swagger 里就能看到并调通 <code>/app/v1/...</code> 的接口——这些接口的鉴权策略和后台不同(买家侧用 app authenticator,token 15 分钟过期),运营拿自己的 admin token 调过去可能直接 401,但也可能某些接口在白名单里(如登录),就变成&quot;后台能直接调买家登录&quot;。作用域裁剪把这种交叉暴露从源头掐了。</p><p>教训:<strong>OpenAPI 文档的可见范围,要当成安全边界管理,不能默认全量。</strong></p><h3 id="_10-2-ent-auto-ddl-的开发爽生产坑" tabindex="-1"><a class="header-anchor" href="#_10-2-ent-auto-ddl-的开发爽生产坑"><span>10.2 Ent auto-DDL 的开发爽生产坑</span></a></h3><p><code>core/.../configs/data.yaml</code> 里默认 <code>migrate: true</code>,Ent 启动时跑 <code>client.Schema.Create()</code> 自动建表建索引。开发时很爽——改 Schema 重启就生效。</p><p>但生产环境的坑:自动 DDL 不带版本化,无法回滚;多实例同时启动会并发 DDL 导致冲突;某些破坏性变更(删列、改列类型)自动 DDL 会直接执行,可能丢数据。</p><p>这个项目当前 <code>configs/</code> 里的 <code>migrate: true</code> 是开发默认,<strong>生产必须关掉,改用版本化迁移工具</strong>(如 atlas、golang-migrate)。这是&quot;开发友好 ≠ 生产就绪&quot;的一个典型例子。</p><h3 id="_10-3-gnostic-openapi-元数据-不写就没有文档" tabindex="-1"><a class="header-anchor" href="#_10-3-gnostic-openapi-元数据-不写就没有文档"><span>10.3 gnostic OpenAPI 元数据:不写就没有文档</span></a></h3><p>核心 proto 里能看到这样的注解:</p><div class="language-proto line-numbers-mode" data-highlighter="prismjs" data-ext="proto"><pre><code><span class="line">repeated ProductTranslation translations = 20 [</span>
<span class="line">    (gnostic.openapi.v3.property) = { ... }</span>
<span class="line">];</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>gnostic.openapi.v3.property</code> 是 gnostic 提供的 OpenAPI 字段元数据注解(描述、示例、是否只读等)。如果不写,生成的 OpenAPI 文档里这个字段就没有描述——Swagger UI 会显示一个光秃秃的字段名,前端工程师看不懂。</p><p>踩坑点:早期 schema 没写这些注解,Swagger 文档对前端几乎不可用,后来补齐。教训:<strong>契约驱动不只是&quot;有文档&quot;,文档的质量也要在 proto 里声明式地保证。</strong></p><hr><h2 id="结语" tabindex="-1"><a class="header-anchor" href="#结语"><span>结语</span></a></h2><p>契约驱动不是一句口号,它是一套从 proto 出发、覆盖接口/数据/错误码/校验/文档/前端 client 的工程闭环。这套闭环的核心价值不是&quot;少写代码&quot;,而是<strong>把容易出错的人工协调,变成源头强制</strong>:接口变更反射到所有消费方,行级隔离变成 Schema 声明,依赖错误在编译期暴露。</p><p>这套方案有它的代价——学习曲线、生成产物体积、生态规模。在选型时,这些代价要诚实评估。但对一个需要多传输、强隔离、审计合规的企业级场景,这套方案的收益是结构性的:它把&quot;能不能做对&quot;从依赖个人自觉,变成了依赖框架强制。</p><p>仓库地址: GitHub <a href="https://github.com/tx7do/go-wind-shop" target="_blank" rel="noopener noreferrer">https://github.com/tx7do/go-wind-shop</a>, Gitee <a href="https://gitee.com/tx7do/go-wind-shop" target="_blank" rel="noopener noreferrer">https://gitee.com/tx7do/go-wind-shop</a>。 所有文中配置和代码均可逐行核对。</p>`,181)])])}const l=s(p,[["render",o]]),r=JSON.parse('{"path":"/posts/go-wind-shop-overview-and-positioning.html","title":"GoWind Shop:一个 proto 文件如何生成后端、前端、文档、校验六路代码","lang":"zh-CN","frontmatter":{"date":"2026-08-11T00:00:00.000Z","category":["GoWind风行"],"tag":["Golang","GoWind","Vue","Shop"],"sticky":10},"headers":[{"level":2,"title":"为什么再聊\\"契约驱动\\"","slug":"为什么再聊-契约驱动","link":"#为什么再聊-契约驱动","children":[]},{"level":2,"title":"一、闭环全景:一份 proto,六路产出","slug":"一、闭环全景-一份-proto-六路产出","link":"#一、闭环全景-一份-proto-六路产出","children":[]},{"level":2,"title":"二、proto 的领域分层:BFF/核心 边界编码进目录","slug":"二、proto-的领域分层-bff-核心-边界编码进目录","link":"#二、proto-的领域分层-bff-核心-边界编码进目录","children":[]},{"level":2,"title":"三、buf 配置逐行:依赖从哪来,产物往哪去","slug":"三、buf-配置逐行-依赖从哪来-产物往哪去","link":"#三、buf-配置逐行-依赖从哪来-产物往哪去","children":[{"level":3,"title":"3.1 buf.yaml:依赖清单","slug":"_3-1-buf-yaml-依赖清单","link":"#_3-1-buf-yaml-依赖清单","children":[]},{"level":3,"title":"3.2 buf.gen.yaml:六个本地插件","slug":"_3-2-buf-gen-yaml-六个本地插件","link":"#_3-2-buf-gen-yaml-六个本地插件","children":[]},{"level":3,"title":"3.3 managed 块:go_package 的集中管理","slug":"_3-3-managed-块-go-package-的集中管理","link":"#_3-3-managed-块-go-package-的集中管理","children":[]}]},{"level":2,"title":"四、OpenAPI 文档的按作用域裁剪:一个容易被忽略的安全细节","slug":"四、openapi-文档的按作用域裁剪-一个容易被忽略的安全细节","link":"#四、openapi-文档的按作用域裁剪-一个容易被忽略的安全细节","children":[{"level":3,"title":"4.1 问题:全局 OpenAPI 会泄漏核心接口","slug":"_4-1-问题-全局-openapi-会泄漏核心接口","link":"#_4-1-问题-全局-openapi-会泄漏核心接口","children":[]},{"level":3,"title":"4.2 解法:按 BFF 作用域单独生成","slug":"_4-2-解法-按-bff-作用域单独生成","link":"#_4-2-解法-按-bff-作用域单独生成","children":[]},{"level":3,"title":"4.3 文档嵌入二进制 + 运行时挂载","slug":"_4-3-文档嵌入二进制-运行时挂载","link":"#_4-3-文档嵌入二进制-运行时挂载","children":[]},{"level":3,"title":"4.4 前端 TypeScript 客户端:同源产物","slug":"_4-4-前端-typescript-客户端-同源产物","link":"#_4-4-前端-typescript-客户端-同源产物","children":[]}]},{"level":2,"title":"五、错误码:从字符串到类型化的工程化","slug":"五、错误码-从字符串到类型化的工程化","link":"#五、错误码-从字符串到类型化的工程化","children":[{"level":3,"title":"5.1 错误码定义在 proto 里","slug":"_5-1-错误码定义在-proto-里","link":"#_5-1-错误码定义在-proto-里","children":[]},{"level":3,"title":"5.2 生成产物:类型化 helper","slug":"_5-2-生成产物-类型化-helper","link":"#_5-2-生成产物-类型化-helper","children":[]},{"level":3,"title":"5.3 对比:这解决了什么","slug":"_5-3-对比-这解决了什么","link":"#_5-3-对比-这解决了什么","children":[]}]},{"level":2,"title":"六、Ent:Schema 即代码,以及四个 feature flag 的取舍","slug":"六、ent-schema-即代码-以及四个-feature-flag-的取舍","link":"#六、ent-schema-即代码-以及四个-feature-flag-的取舍","children":[{"level":3,"title":"6.1 Ent 生成命令逐行","slug":"_6-1-ent-生成命令逐行","link":"#_6-1-ent-生成命令逐行","children":[]},{"level":3,"title":"6.2 Schema 即代码:Mixin 统一审计列","slug":"_6-2-schema-即代码-mixin-统一审计列","link":"#_6-2-schema-即代码-mixin-统一审计列","children":[]},{"level":3,"title":"6.3 Ent vs GORM vs sqlc:三种数据层方案对比","slug":"_6-3-ent-vs-gorm-vs-sqlc-三种数据层方案对比","link":"#_6-3-ent-vs-gorm-vs-sqlc-三种数据层方案对比","children":[]}]},{"level":2,"title":"七、Wire:编译期依赖注入的取舍","slug":"七、wire-编译期依赖注入的取舍","link":"#七、wire-编译期依赖注入的取舍","children":[{"level":3,"title":"7.1 injector 桩与 ProviderSet","slug":"_7-1-injector-桩与-providerset","link":"#_7-1-injector-桩与-providerset","children":[]},{"level":3,"title":"7.2 Wire vs 运行时 DI 的对比","slug":"_7-2-wire-vs-运行时-di-的对比","link":"#_7-2-wire-vs-运行时-di-的对比","children":[]}]},{"level":2,"title":"八、FieldMask:proto 怎么驱动部分更新","slug":"八、fieldmask-proto-怎么驱动部分更新","link":"#八、fieldmask-proto-怎么驱动部分更新","children":[{"level":3,"title":"8.1 问题:全量更新会覆盖","slug":"_8-1-问题-全量更新会覆盖","link":"#_8-1-问题-全量更新会覆盖","children":[]},{"level":3,"title":"8.2 proto 的 FieldMask","slug":"_8-2-proto-的-fieldmask","link":"#_8-2-proto-的-fieldmask","children":[]},{"level":3,"title":"8.3 Ent 侧的落地","slug":"_8-3-ent-侧的落地","link":"#_8-3-ent-侧的落地","children":[]}]},{"level":2,"title":"九、横向对比:这套方案 vs 另三种主流路径","slug":"九、横向对比-这套方案-vs-另三种主流路径","link":"#九、横向对比-这套方案-vs-另三种主流路径","children":[{"level":3,"title":"路径 A:OpenAPI-first(Swagger 注解驱动)","slug":"路径-a-openapi-first-swagger-注解驱动","link":"#路径-a-openapi-first-swagger-注解驱动","children":[]},{"level":3,"title":"路径 B:手写接口 + 手写文档","slug":"路径-b-手写接口-手写文档","link":"#路径-b-手写接口-手写文档","children":[]},{"level":3,"title":"路径 C:GraphQL + ORM","slug":"路径-c-graphql-orm","link":"#路径-c-graphql-orm","children":[]},{"level":3,"title":"路径 D(本方案):proto-first + Ent + Wire","slug":"路径-d-本方案-proto-first-ent-wire","link":"#路径-d-本方案-proto-first-ent-wire","children":[]}]},{"level":2,"title":"十、三个实战踩坑点","slug":"十、三个实战踩坑点","link":"#十、三个实战踩坑点","children":[{"level":3,"title":"10.1 OpenAPI 作用域裁剪:不做等于裸奔","slug":"_10-1-openapi-作用域裁剪-不做等于裸奔","link":"#_10-1-openapi-作用域裁剪-不做等于裸奔","children":[]},{"level":3,"title":"10.2 Ent auto-DDL 的开发爽生产坑","slug":"_10-2-ent-auto-ddl-的开发爽生产坑","link":"#_10-2-ent-auto-ddl-的开发爽生产坑","children":[]},{"level":3,"title":"10.3 gnostic OpenAPI 元数据:不写就没有文档","slug":"_10-3-gnostic-openapi-元数据-不写就没有文档","link":"#_10-3-gnostic-openapi-元数据-不写就没有文档","children":[]}]},{"level":2,"title":"结语","slug":"结语","link":"#结语","children":[]}],"git":{"updatedTime":1786420471000,"contributors":[{"name":"Bobo","username":"Bobo","email":"yanglinbo@gmail.com","commits":1,"url":"https://github.com/Bobo"}],"changelog":[{"hash":"e2ce92e3de85c275b0b5b0183aebe03348e2dd79","time":1786420471000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: add posts."}]},"filePathRelative":"posts/go-wind-shop-overview-and-positioning.md","excerpt":"\\n<h2>为什么再聊\\"契约驱动\\"</h2>\\n<p>\\"契约驱动(contract-driven)\\"这个词被用滥了。大多数项目里它的实际含义是:后端写完接口,用 Swagger 注解生成一份文档,前端照着文档手写 fetch。文档和实现谁是事实源?没人说得清。接口改了文档没改,文档改了实现没改,前后端各自演进直到某天线上 404。</p>\\n<p>这篇文章不讲概念,讲一个<strong>可运行的工程闭环</strong>:以 <code>.proto</code> 为唯一事实源,一次 <code>buf generate</code> 同时产出六路产物——后端 gRPC 桩、后端 HTTP 桩、错误码 helper、请求校验器、PII 脱敏器、OpenAPI 文档,以及给前端的 TypeScript 客户端。文中所有配置和代码都来自一个真实仓库 go-wind-shop(GitHub: <a href=\\"https://github.com/tx7do/go-wind-shop\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">https://github.com/tx7do/go-wind-shop</a>, Gitee: <a href=\\"https://gitee.com/tx7do/go-wind-shop\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">https://gitee.com/tx7do/go-wind-shop</a>),你可以逐行核对。</p>"}');export{l as comp,r as data};
